function pll_data_s = rfdude_pll_run(pll_inputs_s, run_options_s)
% Generated by GitHub Copilot under Lance Lascari's direction.
% Single/design-target sweep runner; the historical core remains a script.
tool_directory=fileparts(mfilename('fullpath'));
if ~isfield(run_options_s,'base_directory')
    run_options_s.base_directory=tool_directory;
end
config_s=struct('pll_inputs_s',pll_inputs_s,'run_options_s',run_options_s);
path_before=path;
cleanup_path=onCleanup(@() path(path_before));
addpath(tool_directory,fullfile(tool_directory,'..','pn'));
rfdude_pll_validate_configuration(config_s,run_options_s.base_directory);
[directory,basename,~]=fileparts(pll_inputs_s.def_filename);
if isempty(directory) || ~is_absolute(directory)
    directory=fullfile(run_options_s.base_directory,directory);
end
if exist(directory,'dir')~=7
    error('Results directory does not exist: %s',directory);
end
dataset_path=fullfile(directory,[basename '_data.mat']);
case_directory=fullfile(directory,[basename '_cases']);
if ~run_options_s.bOverwriteResults && ...
        (exist(dataset_path,'file') || exist(case_directory,'dir'))
    error('Results already exist; choose another filename or explicitly enable overwrite');
end
[ok,message]=mkdir(case_directory);
if ~ok
    error('Cannot create results directory: %s',message);
end
if run_options_s.bRunSweep
    values=run_options_s.sweep_values(:).';
    parameter=run_options_s.sweep_parameter;
else
    values=pll_inputs_s.BW_desired_Hz;
    parameter='BW_desired_Hz';
end
pll_data_s=struct('format_version',1,'created',datestr(now,31), ...
    'config_s',config_s,'parameter',parameter,'values',values, ...
    'dataset_path',dataset_path,'cases',{{}},'completed',false(1,numel(values)));
pll_data_s.metric_notes={ ...
    'Integrated noise: double-sided RMS phase error in radians, existing integrate_ssb_pnoise method'; ...
    'EVM dB: 20*log10(RMS phase error); EVM percent: 100*RMS phase error (small-angle estimate)'; ...
    'Residual FM: existing calculate_residual_fm method, flagged unverified by its author'; ...
    'Settling is model-dependent, not guaranteed lock time; NaN with status not_settled is not zero'; ...
    'Offset noise: linear interpolation of dBc/Hz against log10(offset frequency)'};
for point_index=1:numel(values)
    requested=pll_inputs_s;
    if run_options_s.bRunSweep
        requested.(parameter)=values(point_index);
    end
    pll_data_s.cases{point_index}=struct('requested_inputs',requested, ...
        'status','pending','message','Not run yet');
end
save_dataset(dataset_path,pll_data_s);
for point_index=1:numel(values)
    requested=pll_data_s.cases{point_index}.requested_inputs;
    fprintf('\nPLL point %d/%d: %s = %.9g\n',point_index,numel(values),parameter,values(point_index));
    try
        result=run_case(requested,run_options_s,case_directory, ...
            sprintf('%s_case%04d.mat',basename,point_index));
        result.status='complete';
        result.message='';
        pll_data_s.completed(point_index)=true;
    catch err
        result=struct('requested_inputs',requested,'status','failed','message',err.message);
        warning('PLL point %d failed: %s',point_index,err.message);
    end
    pll_data_s.cases{point_index}=result;
    save_dataset(dataset_path,pll_data_s);
end
fprintf('PLL dataset saved: %s\n',dataset_path);
if ~any(pll_data_s.completed)
    error('All PLL points failed; inspect the saved dataset for errors: %s',dataset_path);
end
if run_options_s.bEnableDataViewer
    cc_pll_data_viewer(pll_data_s);
end
end

function result=run_case(requested,options,output_directory,output_name)
directory_before=pwd;
visibility_before=get(0,'defaultfigurevisible');
figures_before=findall(0,'type','figure');
cleanup=onCleanup(@() restore_state(directory_before,visibility_before,figures_before,options.bShowCorePlots));
if ~options.bShowCorePlots
    set(0,'defaultfigurevisible','off');
end
pll_inputs_s=requested;
if isfield(options,'vco_profile_s')
    [pn_struct,vco_selection_s]=select_pn_profile(options.vco_profile_s, ...
        requested.fout_desired_Hz/requested.mult,'interpolate');
    vco_characterization=pn_struct;
    [~,case_basename]=fileparts(output_name);
    pll_inputs_s.FileVCO=fullfile(output_directory,[case_basename '_vco.mat']);
    save(pll_inputs_s.FileVCO,'pn_struct','-v7');
end
for source={'TCXO','VCO'}
    name=['File' source{1}];
    filename=pll_inputs_s.(name);
    if ~is_absolute(filename)
        filename=fullfile(options.base_directory,filename);
    end
    pll_inputs_s.(name)=filename;
end
figure_numbers=get(figures_before,'number');
if iscell(figure_numbers)
    figure_numbers=cell2mat(figure_numbers);
end
pll_inputs_s.figure_number_base=max([0;figure_numbers(:)]);
pll_inputs_s.def_filename=output_name;
cd(output_directory);
core_transcript=evalc('rfdude_pll_oct_0p1;');
fprintf('%s',core_transcript);
validateattributes([C1 C2 R2 C3 R3],{'numeric'},{'real','finite','positive'});
validateattributes(pn_struct.n,{'numeric'},{'real','finite','numel',numel(pn_struct.f)});
result=struct('requested_inputs',requested,'effective_inputs',pll_inputs_s, ...
    'components',struct('C1',C1,'C2',C2,'R2',R2,'C3',C3,'R3',R3), ...
    'BW_actual_Hz',BW_actual,'PM_actual_deg',PM_actual,'Kvco_Hz_volt',Kvco_Hz_volt, ...
    'Fvco_Hz',Fvco,'pn_struct',pn_struct,'core_transcript',core_transcript);
result.contributors_dBc_Hz=20*log10(abs([Nvco_loop(:) Ntcxo_loop(:) ...
    N_out_R2(:) N_out_R3(:) N_pd(:)]));
result.contributor_names={'VCO','Reference','R2','R3','Phase detector'};
result.effective_inputs.Kvco_Hz_volt=Kvco_Hz_volt;
result.source_noise=struct();
if requested.bUseVCOFromFile
    result.source_noise.VCO=pn_struct_vco;
    if isfield(options,'vco_profile_s')
        result.vco_selection_s=vco_selection_s;
        result.vco_characterization=vco_characterization;
    end
end
if requested.bUseTCXOFromFile
    result.source_noise.TCXO=pn_struct_tcxo;
end
ll=options.integration_lower_Hz;
ul=options.integration_upper_Hz;
npts=1+(50*(log10(pn_struct.f(end))-log10(pn_struct.f(1))));
x=logspace(log10(pn_struct.f(1)),log10(pn_struct.f(end)),npts);
pn_dBc_Hz=interp1(log10(pn_struct.f),pn_struct.n,log10(x));
result.integrated_noise_rad=integrate_ssb_pnoise(x,pn_dBc_Hz,ll,ul);
result.EVM_dB=20*log10(result.integrated_noise_rad);
result.EVM_percent=100*result.integrated_noise_rad;
result.residual_FM_Hz=calculate_residual_fm(x,pn_dBc_Hz,ll,ul);
result.noise_offsets_Hz=options.noise_offsets_Hz;
result.noise_at_offsets_dBc_Hz=interp1(log10(pn_struct.f),pn_struct.n,log10(options.noise_offsets_Hz));
result.small_signal=struct('status','disabled','settling_time_s',NaN);
result.nonlinear=struct('status','disabled','settling_time_s',NaN);
if bDoTransient
    result.small_signal=transient_result(transient_t_s, ...
        transient_freq_Hz-fout_desired_Hz,transient_lock_time_s);
end
if bDoTransientNonlinear
    result.nonlinear=transient_result(nl_t_s,nl_foff_Hz,nl_lock_time_s);
    result.nonlinear.phase_error_cycles=nl_phase_err_cyc;
    result.nonlinear.tuning_voltage_V=nl_vtune_V;
    result.nonlinear.cycle_slips=nl_slips;
end
end

function result=transient_result(t,error_Hz,settling_time)
status='settled';
if isnan(settling_time)
    status='not_settled';
end
result=struct('status',status,'time_s',t,'frequency_error_Hz',error_Hz, ...
    'settling_time_s',settling_time);
end

function restore_state(directory,visibility,figures_before,show_plots)
cd(directory);
set(0,'defaultfigurevisible',visibility);
if ~show_plots
    figures_now=findall(0,'type','figure');
    for k=1:numel(figures_now)
        if ~any(figures_now(k)==figures_before)
            close(figures_now(k));
        end
    end
end
end

function save_dataset(filename,pll_data_s)
temporary=[tempname(fileparts(filename)) '.mat'];
cleanup=onCleanup(@() remove_temporary(temporary));
save(temporary,'pll_data_s','-v7');
[ok,message]=movefile(temporary,filename,'f');
if ~ok
    error('Cannot save PLL dataset: %s',message);
end
end

function remove_temporary(filename)
if exist(filename,'file')==2
    delete(filename);
end
end

function yes=is_absolute(filename)
yes=~isempty(filename) && (filename(1)==filesep || ...
    ~isempty(regexp(filename,'^[A-Za-z]:[\\/]','once')));
end
